use verus::prelude::*;

verus! {

    /// Returns the longest character‐sequence in `strings` (by length), or `None` if
    /// `strings` is empty.  If there are multiple sequences of maximal length, the
    /// one with the smallest index is chosen.
    ///
    /// Specification:
    /// - If `strings.len() == 0`, then we return `None`.
    /// - Otherwise we return `Some(v)` where
    ///     * `v == strings[i]` for some `i < strings.len()`,
    ///     * for all `j < strings.len()`, `strings[j].len() <= v.len()`, and
    ///     * for all `j < i`, `strings[j].len() < v.len()`.
    ///
    pub fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>>
        ensures
            if strings.len() == 0 {
                result.is_None()
            } else {
                result.is_Some() &&
                // there exists an index i witnessing the returned sequence
                exists |i: usize| 
                    i < strings.len() &&
                    // the result matches strings[i]
                    result.get_Some_0() == strings[i] &&
                    // no other string is longer
                    forall(|j: usize| j < strings.len() ==> strings[j].len() <= result.get_Some_0().len()) &&
                    // and no earlier string ties that maximum length
                    forall(|j: usize| j < i             ==> strings[j].len() <  result.get_Some_0().len())
            }
    {
        // Handle the empty‐input case immediately.
        if strings.len() == 0 {
            return None;
        }

        // We know strings.len() >= 1 here.
        // Initialize our "best so far" to index 0.
        let mut best_idx: usize = 0;
        let mut best: Vec<char> = strings[0].clone();

        // We'll scan from i = 1 .. strings.len()-1.
        let mut i: usize = 1;
        while i < strings.len() {
            // Invariants to maintain:
            //  1) 0 <= best_idx < i
            //  2) best == strings[best_idx]
            //  3) for all j < i, strings[j].len() <= best.len()
            //  4) for all j < best_idx, strings[j].len() < best.len()
            invariant 0 <= best_idx && best_idx < i;
            invariant best == strings[best_idx];
            invariant forall(|j: usize| j < i          ==> strings[j].len() <= best.len());
            invariant forall(|j: usize| j < best_idx  ==> strings[j].len() <  best.len());
            decreases strings.len() - i;

            let curr = &strings[i];
            if curr.len() > best.len() {
                // Found a strictly longer sequence: update best
                best = curr.clone();
                best_idx = i;
            }
            i += 1;
        }

        // At the end, `best` is exactly strings[best_idx], and by the invariants
        // it satisfies the maximal‐length and earliest‐index properties.
        Some(best)
    }

} // end verus!